#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-11-01
#
# The PR Playground gate must read a PR's changed files from the paginated
# files API, never from the PR diff. Reference: #4571, #4965.
#
# GitHub refuses a diff past 300 files (HTTP 406). The gate read a
# name-only diff, got nothing back, and failed closed with "Could not read
# the PR diff" on a 574-file PR whose every path is inert. The stub gh in
# fixtures/playground-gate-gh-stub answers like GitHub: the diff call 406s
# past 300 files, the files API returns every path. Nothing reaches the
# network.
#
# Outputs go to files and are grepped there: no here-strings, no pipes
# into grep -q (#603, ork#3348).

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
DECISION="$PROJECT_ROOT/scripts/ci/playground-gate-decision.sh"
STUB_BIN="$SCRIPT_DIR/fixtures/playground-gate-gh-stub"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'; NC=$'\033[0m'
PASS=0; FAIL=0
log_pass() { echo "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
log_fail() { echo "  ${RED}✗${NC} $1"; FAIL=$((FAIL + 1)); }
section() { echo; echo "${YELLOW}$1${NC}"; }

WORK_DIR="$(mktemp -d "${TMPDIR:-/tmp}/ork-gate-files-api.XXXXXX")"
trap 'rm -rf "$WORK_DIR"' EXIT
CALLS="$WORK_DIR/calls.log"
OUT="$WORK_DIR/out.txt"

# Docs lab dirs are docs/<type><sep><slug>/ with sep two hyphens. Built by
# concatenation so this file holds no literal pair (same as the gate).
sep=-
sep="${sep}${sep}"

echo "=========================================="
echo "  PR Playground gate: files API read"
echo "=========================================="

section "0. Fixtures exist"
if [ -x "$STUB_BIN/gh" ] && [ -f "$DECISION" ]; then
  log_pass "stub gh and decision script present"
else
  log_fail "missing $STUB_BIN/gh (executable) or $DECISION"
  echo "  Passed: ${PASS}  Failed: ${FAIL}"
  exit 1
fi

# Runs the real decision script with the stub gh first on PATH and an empty
# stdin, so it must fetch the list itself (the CI shape).
decide_live() { # files_file
  : > "$CALLS"
  env -u GITHUB_OUTPUT \
    PATH="$STUB_BIN:$PATH" GH_STUB_FILES="$1" GH_STUB_LOG="$CALLS" \
    GITHUB_REPOSITORY="yonatangross/orchestkit" PR_NUMBER=4965 \
    HEAD_REF="fix/playground-graveyard-4571" PR_AUTHOR="octocat" IS_FORK="false" \
    bash "$DECISION" < /dev/null > "$OUT" 2>&1
}
message() { sed -n 's/^message=//p' "$OUT"; }

BIG_INERT="$WORK_DIR/big-inert.txt"
for i in $(seq 1 350); do
  printf 'docs/chore%sold-%s/index.html\n' "$sep" "$i"
done > "$BIG_INERT"

section "1. 350 inert paths: no playground, read from the files API"
decide_live "$BIG_INERT"
if grep -qx 'required=false' "$OUT" && ! grep -qF 'Could not read the PR diff' "$OUT"; then
  log_pass "decided from the real list: $(message)"
else
  log_fail "failed closed instead of reading the files API: $(message)"
fi
# -e: the pattern starts with two hyphens, which grep would parse as an
# option without it.
if grep -qF -e "${sep}paginate" "$CALLS" && grep -qF 'pulls/4965/files' "$CALLS" && grep -qF 'per_page=100' "$CALLS"; then
  log_pass "files API read is paginated at per_page=100"
else
  log_fail "files API not read paginated at per_page=100; calls: $(tr '\n' ' ' < "$CALLS")"
fi
if grep -qE '^pr diff' "$CALLS"; then
  log_fail "gate still calls gh pr diff, which 406s past 300 files"
else
  log_pass "gate no longer calls gh pr diff"
fi

section "2. 350 inert paths plus one hook change: playground required"
BIG_MIXED="$WORK_DIR/big-mixed.txt"
cp "$BIG_INERT" "$BIG_MIXED"
echo "src/hooks/src/prompt/foo.ts" >> "$BIG_MIXED"
decide_live "$BIG_MIXED"
if grep -qx 'required=true' "$OUT" && grep -qF 'user-facing' "$OUT"; then
  log_pass "the hook change is caught in a 351-file PR"
else
  log_fail "a hook change in a 351-file PR was not caught: $(message)"
fi

section "3. An empty answer still fails closed"
EMPTY_LIST="$WORK_DIR/empty.txt"
: > "$EMPTY_LIST"
decide_live "$EMPTY_LIST"
if grep -qx 'required=true' "$OUT" && grep -qF 'fail-closed' "$OUT"; then
  log_pass "empty files API answer requires a playground"
else
  log_fail "empty files API answer did not fail closed: $(message)"
fi

echo
echo "=========================================="
echo "  Passed: ${GREEN}${PASS}${NC}  Failed: ${RED}${FAIL}${NC}"
echo "=========================================="
[ "$FAIL" -eq 0 ]
